import{_ as s,H as a,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"07 | 如何给Kubernetes社区贡献源码？","description":"","frontmatter":{},"headers":[{"level":2,"title":"Kubernetes 项目工作流设计","slug":"kubernetes-项目工作流设计","link":"#kubernetes-项目工作流设计","children":[]},{"level":2,"title":"步骤 1：在 GitHub 上 Fork Kubernetes 项目","slug":"步骤-1-在-github-上-fork-kubernetes-项目","link":"#步骤-1-在-github-上-fork-kubernetes-项目","children":[]},{"level":2,"title":"步骤 2：克隆 Fork 项目到本地","slug":"步骤-2-克隆-fork-项目到本地","link":"#步骤-2-克隆-fork-项目到本地","children":[]},{"level":2,"title":"步骤 3：同步上游 master 分支最新代码","slug":"步骤-3-同步上游-master-分支最新代码","link":"#步骤-3-同步上游-master-分支最新代码","children":[]},{"level":2,"title":"步骤 4：创建一个工作分支","slug":"步骤-4-创建一个工作分支","link":"#步骤-4-创建一个工作分支","children":[]},{"level":2,"title":"步骤 5：在工作分支变更代码","slug":"步骤-5-在工作分支变更代码","link":"#步骤-5-在工作分支变更代码","children":[]},{"level":2,"title":"步骤 6：将变更推送到远端仓库","slug":"步骤-6-将变更推送到远端仓库","link":"#步骤-6-将变更推送到远端仓库","children":[]},{"level":2,"title":"步骤 7：创建一个 Pull Request","slug":"步骤-7-创建一个-pull-request","link":"#步骤-7-创建一个-pull-request","children":[{"level":3,"title":"进行代码审查","slug":"进行代码审查","link":"#进行代码审查","children":[]},{"level":3,"title":"压缩提交","slug":"压缩提交","link":"#压缩提交","children":[]}]},{"level":2,"title":"其他后续操作","slug":"其他后续操作","link":"#其他后续操作","children":[{"level":3,"title":"合并提交","slug":"合并提交","link":"#合并提交","children":[]},{"level":3,"title":"撤销提交","slug":"撤销提交","link":"#撤销提交","children":[]}]},{"level":2,"title":"课程总结","slug":"课程总结","link":"#课程总结","children":[]},{"level":2,"title":"课后练习","slug":"课后练习","link":"#课后练习","children":[]}],"relativePath":"Kubernetes源码剖析与实战/07｜如何给Kubernetes社区贡献源码？.md","filePath":"Kubernetes源码剖析与实战/07｜如何给Kubernetes社区贡献源码？.md","lastUpdated":1795530017000}'),p={name:"Kubernetes源码剖析与实战/07｜如何给Kubernetes社区贡献源码？.md"};function i(l,e,r,o,c,u){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="_07-如何给kubernetes社区贡献源码" tabindex="-1">07 | 如何给Kubernetes社区贡献源码？ <a class="header-anchor" href="#_07-如何给kubernetes社区贡献源码" aria-label="Permalink to &quot;07 | 如何给Kubernetes社区贡献源码？&quot;">​</a></h1><p>你好，我是孔令飞。</p><p>本节课，我来介绍下 Kubernetes 的源码贡献流程，其实就是标准的 GitHub 工作流。如果你想给 Kubernetes 贡献源码，需要遵照 Kubernetes 的源码贡献流程。另外，因为 Kubernetes的 GitHub 工作流非常规范且详细，所以对于我们自己设计 GitHub 工作流也是很有参考意义的。OneX 项目的 GitHub 工作流，就参考了 Kubernetes 的工作流设计和步骤。</p><p>接下来，我们就详细看下 Kubernetes GitHub 工作流的具体操作。</p><h2 id="kubernetes-项目工作流设计" tabindex="-1">Kubernetes 项目工作流设计 <a class="header-anchor" href="#kubernetes-项目工作流设计" aria-label="Permalink to &quot;Kubernetes 项目工作流设计&quot;">​</a></h2><p>Kubernetes 项目遵循标准的 GitHub 工作流，Kuberntes 社区给出了一个流程图，详细的说明了整个流程。流程图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/07/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/07/1.png" alt=""></a></p><ul><li>图片来源网络</li></ul><p>接下来，我们来看一下具体的操作流程。</p><h2 id="步骤-1-在-github-上-fork-kubernetes-项目" tabindex="-1">步骤 1：在 GitHub 上 Fork Kubernetes 项目 <a class="header-anchor" href="#步骤-1-在-github-上-fork-kubernetes-项目" aria-label="Permalink to &quot;步骤 1：在 GitHub 上 Fork Kubernetes 项目&quot;">​</a></h2><p>具体操作如下：</p><ol><li><p>访问 <a href="https://github.com/kubernetes/kubernetes" target="_blank" rel="noreferrer">https://github.com/kubernetes/kubernetes</a></p></li><li><p>点击右上角的 Fork 按钮，Fork Kubernetes 项目</p></li></ol><h2 id="步骤-2-克隆-fork-项目到本地" tabindex="-1">步骤 2：克隆 Fork 项目到本地 <a class="header-anchor" href="#步骤-2-克隆-fork-项目到本地" aria-label="Permalink to &quot;步骤 2：克隆 Fork 项目到本地&quot;">​</a></h2><p>执行以下命令，将 Fork 项目克隆到本地指定的路径：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ export working_dir=&quot;$(go env GOPATH)/src/github.com/colin404&quot; # 设置 kubernetes</span></span>
<span class="line"><span>$ export user=&lt;​your github profile name&gt; # 注意，这里需要设置 user 为你的 GitHub 用户名</span></span>
<span class="line"><span>$ mkdir -p $working_dir</span></span>
<span class="line"><span>$ cd $working_dir</span></span>
<span class="line"><span>$ git clone https://github.com/$user/kubernetes.git # 克隆 Fork 的 kubernetes 项目到</span></span>
<span class="line"><span>$ cd $working_dir/kubernetes</span></span>
<span class="line"><span>$ git remote add upstream https://github.com/kubernetes/kubernetes.git # 添加一个名</span></span>
<span class="line"><span>$ git remote set-url --push upstream no_push # 设置永不向 upstream 推送代码变更</span></span>
<span class="line"><span>$ git remote -v # 确认远程仓库设置正确</span></span></code></pre></div><p>在 GitHub 中，“上游”（upstream）通常指代原始仓库，而 “origin” 指代你 Fork 出来的仓库。通过这种方式，你可以方便地与原始仓库保持同步，同时在自己的仓库中进行修改和开发。</p><p>另外，要禁止向 upstream 推送代码，如果想给 upstream 仓库提交代码贡献，需要通过 PR的方式，这个后面会介绍。</p><h2 id="步骤-3-同步上游-master-分支最新代码" tabindex="-1">步骤 3：同步上游 master 分支最新代码 <a class="header-anchor" href="#步骤-3-同步上游-master-分支最新代码" aria-label="Permalink to &quot;步骤 3：同步上游 master 分支最新代码&quot;">​</a></h2><p>在创建工作分支之前，我们还需要将本地的主分支更新到最新的状态，更新方法如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cd $working_dir/kubernetes # 切换到 kubernetes 项目仓库所在的目录</span></span>
<span class="line"><span>$ git fetch upstream # 从远程仓库 upstream 中获取最新的更改，但不会自动合并到你的当前分支</span></span>
<span class="line"><span>$ git checkout master # 切换到本地的 master 分支</span></span>
<span class="line"><span>$ git rebase upstream/master # 同步 upstream/master 分支的最新变更到本地的 master 分支</span></span></code></pre></div><p>注意：主分支可能被命名为 main 或 master，具体取决于代码仓库，kubernetes 项目的主分支名为 master。</p><p>在创建一个新的修复分支或者新功能分支时，要确保基于 upstream 最新的 master 代码来创建，这样能够基于最新的代码来开发，并且可以尽最大可能降低未来分支代码合并到上游master 分支时的代码冲突。</p><h2 id="步骤-4-创建一个工作分支" tabindex="-1">步骤 4：创建一个工作分支 <a class="header-anchor" href="#步骤-4-创建一个工作分支" aria-label="Permalink to &quot;步骤 4：创建一个工作分支&quot;">​</a></h2><p>基于本地 master 分支，创建本地的工作分支：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git checkout -b feature-myfeature</span></span>
<span class="line"><span>之后，我们就可以在 feature-myfeature 分支，开发代码、编译代码、 测试代码。</span></span></code></pre></div><p>这里要注意，在基于本地 master 分支创建工作分支之前，要确保执行步骤 3，确保本地master 分支代码跟上游 master 分支代码是一致的。</p><p>另外，这里要注意 Kubernetes 的分支命名规则为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feature-xxx：功能分支</span></span>
<span class="line"><span>fix-xxx：修复分支</span></span>
<span class="line"><span>release-xxx：发布分支</span></span></code></pre></div><h2 id="步骤-5-在工作分支变更代码" tabindex="-1">步骤 5：在工作分支变更代码 <a class="header-anchor" href="#步骤-5-在工作分支变更代码" aria-label="Permalink to &quot;步骤 5：在工作分支变更代码&quot;">​</a></h2><p>之后，我们就可以基于工作分支来开发 Kubernetes 源码。在开发过程中，我们可以根据需求提交代码变更。这里建议的流程如下：</p><ol><li>修改代码</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>执行 git add添加期望的变更内容</span></span>
<span class="line"><span>执行 git commit -m &quot;some useful commit message&quot;</span></span>
<span class="line"><span>如果你需要更多的变更，变更完之后，可以执行 git commit --amend 命令，来将变更</span></span></code></pre></div><ul><li>内容追加到上一次的提交中</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 代码变更</span></span>
<span class="line"><span>$ git add &lt;​expected changes&gt;</span></span>
<span class="line"><span>$ git commit --amend</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>关于 git commit --amend 的详细介绍，你可以可参考：amend your previous commit</span></span></code></pre></div><p>另外，我们需要定期确保分支代码和上游的 master 代码的一致性。原因上面其实有介绍，就是确保我们基于最新的代码来开发，这样可以尽最大可能避免未来合并到上游 master 分支时的潜在冲突。</p><p>保持同步的方法也很简单，就是首先切换到工作分支，然后执行下述命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git checkout feature-myfeature</span></span>
<span class="line"><span>$ git fetch upstream</span></span>
<span class="line"><span>$ git rebase upstream/master</span></span>
<span class="line"><span>注意，不要使用 git pull 来代替 git fetch 和 git rebase，因为 git pull 会进行</span></span></code></pre></div><p>合并，并产生一个合并提交记录，这会使 Kubernetes 仓库的提交历史变得混乱，并且这也违反了提交记录应该遵循整洁和清晰的原则。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你还可以使用以下两种方法来同步上游的 master 代码（两种方法都是确保git pull 时使用</span></span>
<span class="line"><span>rebase 而不是 merge）：</span></span></code></pre></div><p>方法 1：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git config branch.autoSetupRebase always # 该命令实际上是通过修改 .git/config 配置来</span></span>
<span class="line"><span>$ git pull upstream master</span></span></code></pre></div><p>方法 2：</p><p>或者直接执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git pull --rebase upstream master</span></span></code></pre></div><h2 id="步骤-6-将变更推送到远端仓库" tabindex="-1">步骤 6：将变更推送到远端仓库 <a class="header-anchor" href="#步骤-6-将变更推送到远端仓库" aria-label="Permalink to &quot;步骤 6：将变更推送到远端仓库&quot;">​</a></h2><p>代码开发完之后，就可以将开发分支推送到远端仓库，命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push -f origin feature-myfeature</span></span></code></pre></div><h2 id="步骤-7-创建一个-pull-request" tabindex="-1">步骤 7：创建一个 Pull Request <a class="header-anchor" href="#步骤-7-创建一个-pull-request" aria-label="Permalink to &quot;步骤 7：创建一个 Pull Request&quot;">​</a></h2><p>可以遵循以下步骤，来创建一个 PR（Pull Request）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>访问 Fork kubernetes GitHub 仓库：https://github.com/&lt;​user&gt;/kubernetes</span></span></code></pre></div><ol start="2"><li>点击 Pull requestss -&gt; New pull request</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/07/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/07/2.png" alt=""></a></p><p>提交的时候要注意：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>base repository 选择 kubernetes/kubernetes，base 选择 maser；</span></span>
<span class="line"><span>head repository 选择 &lt;​user&gt;/kubernetes，compare 选择 feature-myfeature；</span></span></code></pre></div><ul><li><p>再次检查变更 Diff；</p></li><li><p>点击 Create pull request 创建 PR。</p></li></ul><h3 id="进行代码审查" tabindex="-1">进行代码审查 <a class="header-anchor" href="#进行代码审查" aria-label="Permalink to &quot;进行代码审查&quot;">​</a></h3><p>PR 提交后，会被分配给一个或多个代码审阅者（reviewers），这些审阅者会对代码进行彻底的审查，尝试从中找到错误的变更、可以改进的代码、不符合风格的代码、以及任何不符合要求的代码变更。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果代码审查后，发现你的代码需要重新改进，你可以重新在 feature-myfeature 分支修</span></span>
<span class="line"><span>改代码，并推送到 feature-myfeature 分支。</span></span></code></pre></div><p>这里建议每个 PR 不要包含很多代码变更，这样的 PR 很难审查，会导致你的 PR 被合入master 的进度变得很缓慢。</p><h3 id="压缩提交" tabindex="-1">压缩提交 <a class="header-anchor" href="#压缩提交" aria-label="Permalink to &quot;压缩提交&quot;">​</a></h3><p>在代码 review 后，我们需要压缩我们的提交记录，以准备最终的 PR 合并。</p><p>我们应该确保最终的提交记录是有意义的（要么是一个里程碑，要么是一个单独、完整的提交），通过合理的提交记录，来使我们的变更变得更加清晰。</p><p>在合并 PR 之前，以下类型的提交应该被压缩：</p><ul><li><p>修复 / 审查反馈</p></li><li><p>拼写错误</p></li><li><p>合并和变基</p></li><li><p>进行中的工作</p></li></ul><p>我们应该确保 PR 中的每一个提交都能够独立编译，并通过测试（这不是必须的）。我们还应该确保合并提交记录被删除，因为这些提交无法通过测试。你可以阅读 interactive rebase来了解更多压缩提交的知识。</p><p>压缩提交的具体操作流程如下：</p><ol><li>检查你的开发分支。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git status</span></span></code></pre></div><p>输出类似于：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>On branch your-contribution</span></span>
<span class="line"><span>Your branch is up to date with &#39;origin/your-contribution&#39;.</span></span>
<span class="line"><span>使用特定的提交哈希开始交互式变基，或者从你的最后一个提交使用 HEAD~&lt;​n&gt; 进行倒数</span></span>
<span class="line"><span>计数，其中 &lt;​n&gt; 表示在变基中要包括的提交数量。</span></span>
<span class="line"><span>$ git rebase -i HEAD~3</span></span></code></pre></div><p>输出类似于：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pick 2ebe926 Original commit</span></span>
<span class="line"><span>pick 31f33e9 Address feedback</span></span>
<span class="line"><span>pick b0315fe Second unit of work</span></span>
<span class="line"><span># Rebase 7c34fc9..b0315ff onto 7c34fc9 (3 commands)</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Commands:</span></span>
<span class="line"><span># p, pick &lt;​commit&gt; = use commit</span></span>
<span class="line"><span># r, reword &lt;​commit&gt; = use commit, but edit the commit message</span></span>
<span class="line"><span># e, edit &lt;​commit&gt; = use commit, but stop for amending</span></span>
<span class="line"><span># s, squash &lt;​commit&gt; = use commit, but meld into previous commit</span></span>
<span class="line"><span># f, fixup &lt;​commit&gt; = like &quot;squash&quot;, but discard this commit&#39;s log message</span></span>
<span class="line"><span>...</span></span></code></pre></div><ol start="3"><li>使用命令行文本编辑器，将要压缩的提交中的单词 “pick” 更改为 “squash”，然后保存你的更改并继续进行变基。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pick 2ebe926 Original commit</span></span>
<span class="line"><span>squash 31f33e9 Address feedback</span></span>
<span class="line"><span>pick b0315fe Second unit of work</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>保存之后，输出应该类似于：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[detached HEAD 61fdded] Second unit of work</span></span>
<span class="line"><span>Date: Thu Mar 5 19:01:32 2020 +0100</span></span>
<span class="line"><span>2 files changed, 15 insertions(+), 1 deletion(-)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Successfully rebased and updated refs/heads/master.</span></span></code></pre></div><ol start="4"><li>强制推送你的更改到远程分支。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push --force-with-lease</span></span></code></pre></div><p>对于诸如自动文档格式化之类的大规模自动修复，工具变更使用一个或多个提交，最后使用一个提交来批量应用修复，这样可以使审阅变得更容易。</p><p>手动压缩提交的替代方法，是使用在 GitHub 中配置的 Prow 和 Tide 自动化：在你的 PR 中添</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>加一个带有 /label tide/merge-method-squash 的评论将触发自动化，以便 GitHub 在</span></span></code></pre></div><p>PR 获得批准后，将你的提交压缩到目标分支上。这种方法简化了对 Git 不太熟悉的人的工作，但在某些情况下最好还是在本地进行压缩。审阅者会注意到这一点，并要求手动压缩。</p><p>通过在本地压缩，你可以控制工作的提交消息，并将大型 PR 分解为逻辑上独立的更改。例如：你有一个 PR，代码已经开发完成，并且有 24 个提交，你对此进行变基，简化更改为两个提交。这两个提交中的每一个，代表一个单一的逻辑更改，并且每个提交消息都总结了更改内容。审阅者看到现在一组更改变得更加易懂，并批准了你的 PR。</p><h2 id="其他后续操作" tabindex="-1">其他后续操作 <a class="header-anchor" href="#其他后续操作" aria-label="Permalink to &quot;其他后续操作&quot;">​</a></h2><p>上面，我们已经按照 Kubernetes 源码的 GitHub 工作流，完成了 PR 的提交。之后 PR 便交给 Kubernetes 项目维护者进行代码 Review。Review 通过后，PR 会被合并到 Kubernetesmaster 分支。在这个过程中，还可能需要你合并提交你的代码，你也可能需要撤销你的提交。</p><p>下面我就来介绍下合并提交和撤销提交的流程。</p><h3 id="合并提交" tabindex="-1">合并提交 <a class="header-anchor" href="#合并提交" aria-label="Permalink to &quot;合并提交&quot;">​</a></h3><p>当你收到 Review 和 Approval 的通知后，说明你的提交已经被压缩（squashed），PR 已经准备好被合并到 master 分支了。</p><p>当 Reviewer 和 Approver 批准你的 PR 之后，PR 会被自动合并到 master 分支。如果你没有压缩你的提交， Kubernetes 项目的维护者可能会在批准 PR 之前要求你压缩你的提交。</p><h3 id="撤销提交" tabindex="-1">撤销提交 <a class="header-anchor" href="#撤销提交" aria-label="Permalink to &quot;撤销提交&quot;">​</a></h3><p>你可以执行以下命令来回滚一个提交。</p><ul><li>创建一个分支，并同步最新的上游代码。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 创建一个分组</span></span>
<span class="line"><span>$ git checkout -b revert-myrevert</span></span>
<span class="line"><span># 同步最新的上游代码</span></span>
<span class="line"><span>$ git fetch upstream</span></span>
<span class="line"><span>$ git rebase upstream/master</span></span></code></pre></div><ul><li>如果你想要撤销的提交是一个合并提交，请使用以下命令：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># SHA 是你希望恢复的合并提交的哈希值</span></span>
<span class="line"><span>$ git revert -m 1 &lt;​SHA&gt;</span></span></code></pre></div><ul><li>如果这是一个单独的提交，请使用以下命令：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># SHA 是你希望恢复的单独提交的哈希值</span></span>
<span class="line"><span>$ git revert &lt;​SHA&gt;</span></span></code></pre></div><ul><li>这将创建一个新的提交来撤销这些更改，将这个新的提交推送到你的远程仓库。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push &lt;​your_remote_name&gt; revert-myrevert</span></span>
<span class="line"><span>最后，基于 revert-myrevert 分支提交一个 PR。</span></span></code></pre></div><h2 id="课程总结" tabindex="-1">课程总结 <a class="header-anchor" href="#课程总结" aria-label="Permalink to &quot;课程总结&quot;">​</a></h2><p>这节课我详细介绍了 Kubernetes 的 GitHub 工作流程及具体的操作流程。这些工作流程，在你的项目开发中也可以参考使用。OneX 项目的工作流设计就借鉴了 Kubernetes 的 GitHub工作流设计。</p><h2 id="课后练习" tabindex="-1">课后练习 <a class="header-anchor" href="#课后练习" aria-label="Permalink to &quot;课后练习&quot;">​</a></h2><ol><li><p>根据 Kubernetes GitHub 工作流，尝试给 Kubernetes 贡献一个 PR。</p></li><li><p>为什么在创建本地工作分支前，本地的 master 分支代码要跟上游 master 分支代码进行同步？</p></li></ol><p>欢迎你在留言区与我交流讨论，如果今天的内容让你有所收获，也欢迎转发给有需要的朋友，我们下节课再见！</p>`,105)])])}const b=s(p,[["render",i]]);export{h as __pageData,b as default};
